        return int(gw or 0), int(gh or 0)

    def nearest(src, items):
        best = None
        best_d = None
        for item in items or []:
            p = pos(item, None)
            if p is None:
                continue
            d = abs(p[0] - src[0]) + abs(p[1] - src[1])
            if best_d is None or d < best_d:
