    def step_away(src, dst):
        if dst is None:
            return [0, 0]
        return [clamp_dir(src[0] - dst[0]), clamp_dir(src[1] - dst[1])]

    def preferred_axis_step(src, dst):
        if dst is None:
            return [0, 0]
        dx = dst[0] - src[0]
        dy = dst[1] - src[1]
        if abs(dx) >= abs(dy):
