        if targets:
            target = nearest((sx, sy), targets)
            return preferred_axis_step((sx, sy), target)
        if enemy_terr:
            target = nearest((sx, sy), enemy_terr)
            return preferred_axis_step((sx, sy), target)
        gw, gh = grid_size()
        if gw and gh:
            return preferred_axis_step((sx, sy), (gw // 2, gh // 2))
        return step_away((sx, sy), (ox, oy))

    # resource_collection and fallback:
    if resources:
        target = nearest((sx, sy), resources)
        move = preferred_axis_step((sx, sy), target)
        if move != [0, 0]:
            return move

    # Deny opponent on collection-like games by moving toward them when no resource target exists.
    if env == "resource_collection":
